#!/usr/bin/env python3
# Validate MCP tool decorator usage (CORE-024)

import ast
import sys
from pathlib import Path

def check_mcp_tools():
    tool_files = Path('src/mcp').glob('*_tools.py')
    violations = []

    for file in tool_files:
        with open(file) as f:
            tree = ast.parse(f.read())

        for node in ast.walk(tree):
            if isinstance(node, ast.FunctionDef):
                # Check if function has @mcp_tool decorator
                has_decorator = any(
                    isinstance(d, ast.Name) and d.id == 'mcp_tool' or
                    isinstance(d, ast.Attribute) and d.attr == 'mcp_tool'
                    for d in node.decorator_list
                )

                if not has_decorator:
                    violations.append(f"{file}:{node.lineno} - {node.name}")

    if violations:
        print("❌ CORE-024 VIOLATION: Undecorated MCP tools found")
        for v in violations:
            print(f"   {v}")
        print("\nAll tools in src/mcp/*_tools.py MUST use @mcp_tool decorator")
        sys.exit(1)

if __name__ == '__main__':
    check_mcp_tools()

